import { createClient } from "npm:@supabase/supabase-js@2.45.0";

const db = createClient(Deno.env.get("SUPABASE_URL")!, Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!, { auth: { persistSession: false } });

const deps: Deps = {
  async addContact(token, payload) {
    const { data, error } = await db.rpc("inbound_contact", { p_token: token, p_payload: payload });
    if (error) { console.error("inbound_contact failed", error.message); throw error; }
    return data as Result;
  },
  async apiRequest(key, method, path, query, body) {
    const { data, error } = await db.rpc("api_request", { p_key: key, p_method: method, p_path: path, p_query: query, p_body: body });
    if (error) { console.error("api_request failed", error.message); throw error; }
    return data as ApiAnswer;
  },
};

Deno.serve((req) => handle(req, deps));

// ---------- handler.ts ----------
// SYNAPSE's API for other apps, two ways in, both made by an Admin in Settings → API.
//
// 1. API keys: read and change contacts, tags and notes.
//
//   GET|POST|PATCH|DELETE https://<project>.supabase.co/functions/v1/api/v1/<path>
//   Authorization: Bearer syn_…        (or X-Api-Key: syn_…)
//
// <path> is me, tags, contacts, contacts/<id>, contacts/<id>/tags[/<tag>], contacts/<id>/notes; see
// 20261102090000_api_keys.sql. The database (api_request) checks the key and does the work, and
// answers { status, body }.
//
// 2. Incoming contact links: Zapier, Make, a website form or a live chat adds or updates a contact
// by POSTing to a secret link, no key needed:
//
//   POST https://<project>.supabase.co/functions/v1/api/incoming/<token>
//   POST https://<project>.supabase.co/functions/v1/api/incoming?token=<token>
//
// Body: JSON { "email": "...", "first_name": "...", "tags": ["VIP"], "message": "..." } or a form
// post (email=...&first_name=...). Needs an email or a phone. The database (inbound_contact) does
// the matching, tagging and logging.
//
// -> 201 { ok, contact_id, created: true }   200 { ok, contact_id, created: false }
//    400 not JSON/form   404 unknown or switched-off link   413 over 64 KB   422 no email/phone
//    429 over 120 a minute

export interface Result { ok: boolean; status: number; error?: string; contact_id?: string; created?: boolean }

export interface ApiAnswer { status: number; body: unknown }

export interface Deps {
  addContact(token: string, payload: Record<string, unknown>): Promise<Result>;
  apiRequest(key: string, method: string, path: string, query: Record<string, string>, body: Record<string, unknown>): Promise<ApiAnswer>;
}

export const MAX_BYTES = 64 * 1024;

const cors = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Methods": "GET, POST, PATCH, DELETE, OPTIONS",
  "Access-Control-Allow-Headers": "Content-Type, Authorization, X-Api-Key, X-Client-Info, Apikey",
};
const json = (status: number, body: unknown) =>
  new Response(JSON.stringify(body), { status, headers: { ...cors, "Content-Type": "application/json" } });

/** Which way in: "incoming" with its token, or "v1" with the path after /v1/ (each part decoded). */
export function route(url: string): { kind: "incoming" | "v1" | null; token: string | null; path: string } {
  const u = new URL(url);
  const parts = u.pathname.split("/").filter(Boolean);
  const at = parts.indexOf("incoming");
  const api = parts.findIndex((p, i) => p === "api" && parts[i + 1] === "v1");
  if (api >= 0 && (at < 0 || api < at)) {
    const rest = parts.slice(api + 2).map((p) => { try { return decodeURIComponent(p); } catch { return p; } });
    return { kind: "v1", token: null, path: rest.filter((p) => !p.includes("/")).join("/") };
  }
  if (at < 0) return { kind: null, token: null, path: "" };
  const t = (u.searchParams.get("token") ?? parts[at + 1] ?? "").trim();
  return { kind: "incoming", token: /^[a-f0-9]{32,128}$/i.test(t) ? t.toLowerCase() : null, path: "" };
}

/** The key from "Authorization: Bearer syn_…" or "X-Api-Key: syn_…". */
export function keyFrom(headers: Headers): string | null {
  const bearer = /^Bearer\s+(.+)$/i.exec((headers.get("authorization") ?? "").trim())?.[1] ?? "";
  return [bearer, headers.get("x-api-key") ?? ""].map((k) => k.trim()).find((k) => /^syn_[a-f0-9]{16,128}$/i.test(k)) ?? null;
}

/** The posted fields, from JSON or a form post. Null when it's neither. */
export function readBody(raw: string, contentType: string): Record<string, unknown> | null {
  const type = contentType.toLowerCase();
  if (type.includes("application/x-www-form-urlencoded")) return Object.fromEntries(new URLSearchParams(raw));
  try {
    const parsed = JSON.parse(raw);
    return parsed && typeof parsed === "object" && !Array.isArray(parsed) ? parsed : null;
  } catch {
    return null;
  }
}

export async function handle(req: Request, deps: Deps): Promise<Response> {
  if (req.method === "OPTIONS") return new Response(null, { status: 200, headers: cors });
  const { kind, token, path } = route(req.url);
  if (kind === "v1") return handleApi(req, path, deps);
  if (!kind) return json(404, { error: "Unknown address. The API is at /functions/v1/api/v1/…; incoming contact links look like /functions/v1/api/incoming/<token>." });
  if (req.method !== "POST") return json(405, { error: "Send a POST request." });
  if (!token) return json(404, { error: "This link is missing its token." });

  const raw = await req.text();
  if (new TextEncoder().encode(raw).length > MAX_BYTES) return json(413, { error: "Too large: send at most 64 KB." });
  const body = readBody(raw, req.headers.get("content-type") ?? "");
  if (!body) return json(400, { error: 'Send JSON like { "email": "jane@example.com", "first_name": "Jane" }, or a form post.' });

  const r = await deps.addContact(token, body).catch(() => null);
  if (!r) return json(500, { error: "Couldn't save the contact. Try again." });
  const { status, ...rest } = r;
  return json(status || (r.ok ? 200 : 400), rest);
}

async function handleApi(req: Request, path: string, deps: Deps): Promise<Response> {
  const key = keyFrom(req.headers);
  if (!key) return json(401, { error: 'Send your API key as "Authorization: Bearer syn_…". Make one in Settings → API.' });
  const method = req.method.toUpperCase();
  if (!["GET", "POST", "PATCH", "DELETE"].includes(method)) return json(405, { error: "Use GET, POST, PATCH or DELETE." });

  let body: Record<string, unknown> = {};
  if (method === "POST" || method === "PATCH") {
    const raw = await req.text();
    if (new TextEncoder().encode(raw).length > MAX_BYTES) return json(413, { error: "Too large: send at most 64 KB." });
    if (raw.trim()) {
      const parsed = readBody(raw, req.headers.get("content-type") ?? "");
      if (!parsed) return json(400, { error: "Send the body as a JSON object." });
      body = parsed;
    }
  }
  const query = Object.fromEntries(new URL(req.url).searchParams);

  const r = await deps.apiRequest(key, method, path, query, body).catch(() => null);
  if (!r || typeof r.status !== "number") return json(500, { error: "Something went wrong. Try again." });
  return json(r.status, r.body ?? {});
}
